589	  async function resolveCompanyIdForAgentReference(req: Request): Promise<string | null> {
590	    const companyIdQuery = req.query.companyId;
591	    const requestedCompanyId =
592	      typeof companyIdQuery === "string" && companyIdQuery.trim().length > 0
593	        ? companyIdQuery.trim()
594	        : null;
595	    if (requestedCompanyId) {
596	      assertCompanyAccess(req, requestedCompanyId);
597	      return requestedCompanyId;
598	    }
599	    if (req.actor.type === "agent" && req.actor.companyId) {
600	      return req.actor.companyId;
601	    }
602	    return null;
603	  }
