605	  async function normalizeAgentReference(req: Request, rawId: string): Promise<string> {
606	    const raw = rawId.trim();
607	    if (isUuidLike(raw)) return raw;
608	
609	    const companyId = await resolveCompanyIdForAgentReference(req);
610	    if (!companyId) {
611	      throw unprocessable("Agent shortname lookup requires companyId query parameter");
612	    }
613	
614	    const resolved = await svc.resolveByReference(companyId, raw);
615	    if (resolved.ambiguous) {
616	      throw conflict("Agent shortname is ambiguous in this company. Use the agent ID.");
617	    }
618	    if (!resolved.agent) {
619	      throw notFound("Agent not found");
620	    }
621	    return resolved.agent.id;
622	  }
